   559  /* Returns true if the variant has no value defined (contains neither an array
   560   * nor a scalar value).
   561   *
   562   * @param v The variant
   563   * @return Is the variant empty */
   564  static UA_INLINE UA_Boolean
   565  UA_Variant_isEmpty(const UA_Variant *v) {
   566      return v->type == NULL;
