   569  /* Returns true if the variant contains a scalar value. Note that empty variants
   570   * contain an array of length -1 (undefined).
   571   *
   572   * @param v The variant
   573   * @return Does the variant contain a scalar value */
   574  static UA_INLINE UA_Boolean
   575  UA_Variant_isScalar(const UA_Variant *v) {
   576      return (v->arrayLength == 0 && v->data > UA_EMPTY_ARRAY_SENTINEL);
   577  }
