   440  Array_encodeBinaryComplex(uintptr_t ptr, size_t length, const UA_DataType *type, Ctx *ctx) {
   441      /* Get the encoding function for the data type. The jumptable at
   442       * UA_BUILTIN_TYPES_COUNT points to the generic UA_encodeBinary method */
   443      size_t encode_index = type->builtin ? type->typeIndex : UA_BUILTIN_TYPES_COUNT;
   444      encodeBinarySignature encodeType = encodeBinaryJumpTable[encode_index];
   445
   446      /* Encode every element */
   447      for(size_t i = 0; i < length; ++i) {
   448          u8 *oldpos = ctx->pos;
   449          status ret = encodeType((const void*)ptr, type, ctx);
   450          ptr += type->memSize;
   451
   452          /* Encoding failed, switch to the next chunk when possible */
   453          if(ret != UA_STATUSCODE_GOOD) {
   454              if(ret == UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED) {
   455                  ctx->pos = oldpos; /* Set buffer position to the end of the last encoded element */
   456                  ret = exchangeBuffer(ctx);
   457                  ptr -= type->memSize; /* Undo to retry encoding the ith element */
   458                  --i;
   459              }
   460              UA_assert(ret != UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED);
   461              if(ret != UA_STATUSCODE_GOOD)
   462                  return ret; /* Unrecoverable fail */
   463          }
   464      }
   465
   466      return UA_STATUSCODE_GOOD;
   467  }
