   469  static status
   470  Array_encodeBinary(const void *src, size_t length, const UA_DataType *type, Ctx *ctx) {
   471      /* Check and convert the array length to int32 */
   472      i32 signed_length = -1;
   473      if(length > UA_INT32_MAX)
   474          return UA_STATUSCODE_BADINTERNALERROR;
   475      if(length > 0)
   476          signed_length = (i32)length;
   477      else if(src == UA_EMPTY_ARRAY_SENTINEL)
   478          signed_length = 0;
   479
   480      /* Encode the array length */
   481      status ret = ENCODE_WITHEXCHANGE(&signed_length, UInt32);
   482
   483      /* Quit early? */
   484      if(ret != UA_STATUSCODE_GOOD || length == 0)
   485          return ret;
   486
   487      /* Encode the content */
   488      if(!type->overlayable)
   489          return Array_encodeBinaryComplex((uintptr_t)src, length, type, ctx);
   490      return Array_encodeBinaryOverlayable((uintptr_t)src, length, type->memSize, ctx);
   491  }
