   493  static status
   494  Array_decodeBinary(void *UA_RESTRICT *UA_RESTRICT dst, size_t *out_length,
   495                     const UA_DataType *type, Ctx *ctx) {
   496      /* Decode the length */
   497      i32 signed_length;
   498      status ret = DECODE_DIRECT(&signed_length, UInt32); /* Int32 */
   499      if(ret != UA_STATUSCODE_GOOD)
   500          return ret;
   501
   502      /* Return early for empty arrays */
   503      if(signed_length <= 0) {
   504          *out_length = 0;
   505          if(signed_length < 0)
   506              *dst = NULL;
   507          else
   508              *dst = UA_EMPTY_ARRAY_SENTINEL;
   509          return UA_STATUSCODE_GOOD;
   510      }
   511
   512      /* Filter out arrays that can obviously not be decoded, because the message
   513       * is too small for the array length. This prevents the allocation of very
   514       * long arrays for bogus messages.*/
   515      size_t length = (size_t)signed_length;
   516      if(ctx->pos + ((type->memSize * length) / 32) > ctx->end)
   517          return UA_STATUSCODE_BADDECODINGERROR;
   518
   519      /* Allocate memory */
   520      *dst = UA_calloc(length, type->memSize);
   521      if(!*dst)
   522          return UA_STATUSCODE_BADOUTOFMEMORY;
   523
   524      if(type->overlayable) {
   525          /* memcpy overlayable array */
   526          if(ctx->end < ctx->pos + (type->memSize * length)) {
   527              UA_free(*dst);
   528              *dst = NULL;
   529              return UA_STATUSCODE_BADDECODINGERROR;
   530          }
   531          memcpy(*dst, ctx->pos, type->memSize * length);
   532          ctx->pos += type->memSize * length;
   533      } else {
   534          /* Decode array members */
   535          uintptr_t ptr = (uintptr_t)*dst;
   535          uintptr_t ptr = (uintptr_t)*dst;
   536          size_t decode_index = type->builtin ? type->typeIndex : UA_BUILTIN_TYPES_COUNT;
   537          for(size_t i = 0; i < length; ++i) {
   538              ret = decodeBinaryJumpTable[decode_index]((void*)ptr, type, ctx);
   539              if(ret != UA_STATUSCODE_GOOD) {
   540                  /* +1 because last element is also already initialized */
   541                  UA_Array_delete(*dst, i+1, type);
   542                  *dst = NULL;
   543                  return ret;
   544              }
   545              ptr += type->memSize;
   546          }
   547      }
   548      *out_length = length;
   549      return UA_STATUSCODE_GOOD;
   550  }
