   564  /* Guid */
   565  ENCODE_BINARY(Guid) {
   566      status ret = UA_STATUSCODE_GOOD;
   567      ret |= ENCODE_DIRECT(&src->data1, UInt32);
   568      ret |= ENCODE_DIRECT(&src->data2, UInt16);
   569      ret |= ENCODE_DIRECT(&src->data3, UInt16);
   570      if(ctx->pos + (8*sizeof(u8)) > ctx->end)
   571          return UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED;
   572      memcpy(ctx->pos, src->data4, 8*sizeof(u8));
   573      ctx->pos += 8;
   574      return ret;
   575  }
