   577  DECODE_BINARY(Guid) {
   578      status ret = UA_STATUSCODE_GOOD;
   579      ret |= DECODE_DIRECT(&dst->data1, UInt32);
   580      ret |= DECODE_DIRECT(&dst->data2, UInt16);
   581      ret |= DECODE_DIRECT(&dst->data3, UInt16);
   582      if(ctx->pos + (8*sizeof(u8)) > ctx->end)
   583          return UA_STATUSCODE_BADDECODINGERROR;
   584      memcpy(dst->data4, ctx->pos, 8*sizeof(u8));
   585      ctx->pos += 8;
   586      return ret;
   587  }
